  rules_eyebrow:'Rules', rules_h1:'Challenge & Funded Account Rules',
  rules_p:'Read this page fully before buying any challenge. Payment means you accept these rules.',
  rules_lang_note:'This page is translated into all 7 site languages.',
  rules_section_caps:'Account Caps', rules_section_risk:'Risk Rules', rules_section_general:'General Rules',
  rule1_title:'Maximum account size', rule1_desc:'No single challenge account can exceed $500,000.',
  rule2_title:'Maximum total capital per trader', rule2_desc:"The combined size of a trader's active/funded accounts cannot exceed $750,000.",
  rule3_title:'Maximum active accounts', rule3_desc:'Each trader may hold at most 3 active accounts (challenge or funded) at the same time.',
  rule4_title:'Floating Risk Rule', rule4_desc:"The risk of a single trade or combined simultaneously open trades must not exceed 3% of the account (for sizes $1,000–$50,000) or 2% (for sizes $100,000 and up). Exceeding this limit due to slippage is not a violation; only a deliberate violation (no stop-loss set, combined with real account equity actually dropping past the limit) counts as a violation.",
  rule5_title:'Minimum trading days', rule5_desc:'You need at least 3 trading days, each with at least 0.5% profit — to pass any evaluation phase, and also (on the funded account itself) as a condition for your first payout request, on every plan including Instant Funding.',
  rule6_title:'80% Single-Trade Rule', rule6_desc:"No single trade's profit may represent more than 80% of the phase's total profit (or, on the instant funding plan, total profit since the account started).",
  rule7_title:'40% Consistency Rule (Funded stage)', rule7_desc:"On a funded account, no single day's profit may exceed 40% of the account's total profit.", rule16_title:'Definition of \"trading day\"', rule16_desc:'The trading day (for the daily loss rule and anywhere else \"day\" is used) is defined by UTC midnight — not your local time zone.', rule17_title:'Margin Call', rule17_desc:'If floating losses exceed your free margin, all positions are closed immediately.', rule18_title:'Challenge Fee Refund', rule18_desc:'Your challenge fee is fully refunded, added on top of your profit share, the first time you successfully request a payout from your funded account.',
  rule8_title:'No CID sharing', rule8_desc:'Sharing your account credentials or login details with anyone else is prohibited and results in immediate account closure.',
  rule9_title:'No hedging', rule9_desc:"Opening opposite-direction positions on the same symbol or correlated symbols across a trader's own accounts is prohibited. (Group hedging is banned and, if discovered, results in the closure of ALL related accounts.)",
  rule10_title:'No cross-account copy-trading', rule10_desc:'Copying trades across multiple accounts to get around the risk rules is prohibited; related accounts are reviewed and may be closed.',
  rule11_title:'No latency arbitrage', rule11_desc:'Exploiting delays between price feeds to profit without genuine market risk is prohibited.',
  rule12_title:'Bots and Expert Advisors', rule12_desc:'Bots that exploit server bugs are prohibited; ordinary EA use is allowed.',
  rule13_title:'Funded-account profit split', rule13_desc:"On a funded account, the trader's base share of profit is 75% (one-step plan), 80% (two/three-step plans), or 50% (instant funding plan); the remainder is the platform's share. Each time the account scales up (every 10% of realized profit), this share increases by 5 percentage points, up to a ceiling of 100%.",
  rule14_title:'Payout schedule', rule14_desc:'For your first payout, at least 14 days must have passed since your first trade on the funded account. After that, each subsequent payout must be at least 7 days after the previous one. Payment is made within 48 hours of approval.',
  rule15_title:'Fair & Uniform Execution', rule15_desc:'Spread, commission, and slippage are applied identically to every trader according to these same fixed, published rules. They are never manually adjusted or targeted to cause a specific trader to fail.',
  rules_footer_note:'Violating any of these rules results in automatic account closure and/or manual review by our team, depending on the case.',

