  rules_eyebrow:'القوانين', rules_h1:'قوانين التحدي والحساب الممول',
  rules_p:'اقرأ هذه الصفحة بالكامل قبل شراء أي تحدي. الدفع يعني موافقتك على هذه القوانين.',
  rules_lang_note:'هذه الصفحة مترجمة إلى جميع لغات الموقع السبع.',
  rules_section_caps:'حدود الحساب', rules_section_risk:'قوانين المخاطرة', rules_section_general:'قوانين عامة',
  rule1_title:'الحد الأقصى لحجم الحساب', rule1_desc:'لا يمكن أن يتجاوز حجم أي حساب تحدٍ 500,000 دولار.',
  rule2_title:'الحد الأقصى لإجمالي رأس المال لكل متداول', rule2_desc:'لا يمكن أن يتجاوز إجمالي حجم حسابات المتداول النشطة/الممولة 750,000 دولار.',
  rule3_title:'الحد الأقصى للحسابات النشطة', rule3_desc:'يمكن لكل متداول امتلاك 3 حسابات نشطة كحد أقصى في نفس الوقت.',
  rule4_title:'قانون المخاطرة العائمة', rule4_desc:'يجب ألا تتجاوز مخاطرة الصفقة الواحدة أو مجموع الصفقات المفتوحة في نفس الوقت 3% من الحساب (للأحجام من 1,000 إلى 50,000 دولار) أو 2% (للأحجام 100,000 دولار فأكثر). تجاوز هذا الحد بسبب الانزلاق السعري لا يُعتبر مخالفة؛ فقط التجاوز المتعمد (عدم وضع وقف خسارة مع انخفاض فعلي في حقوق الحساب يتجاوز الحد) يُعتبر مخالفة.',
  rule5_title:'الحد الأدنى لأيام التداول', rule5_desc:'تحتاج إلى 3 أيام تداول على الأقل، كل يوم بربح لا يقل عن 0.5% — لاجتياز أي مرحلة تقييم، وأيضاً (على الحساب الممول نفسه) كشرط لأول طلب سحب، في جميع الخطط بما فيها التمويل الفوري.',
  rule6_title:'قانون الصفقة الواحدة 80%', rule6_desc:'لا يجوز أن يمثل ربح أي صفقة واحدة أكثر من 80% من إجمالي ربح المرحلة (أو، في خطة التمويل الفوري، إجمالي الربح منذ بدء الحساب).',
  rule7_title:'قانون الاتساق 40% (مرحلة التمويل)', rule7_desc:'في الحساب الممول، يجب ألا يتجاوز ربح أي يوم واحد 40% من إجمالي ربح الحساب.', rule16_title:'تعريف \"يوم التداول\"', rule16_desc:'يوم التداول يُحدَّد بمنتصف الليل بالتوقيت العالمي (UTC) — وليس توقيتك المحلي.', rule17_title:'نداء الهامش', rule17_desc:'إذا تجاوزت الخسائر العائمة هامشك الحر، تُغلق جميع الصفقات فوراً.', rule18_title:'استرداد رسوم التحدي', rule18_desc:'يتم استرداد رسوم التحدي بالكامل، إضافة إلى حصتك من الأرباح، في أول مرة تطلب فيها بنجاح سحب أرباح من حسابك الممول.',
  rule8_title:'حظر مشاركة بيانات الحساب (CID)', rule8_desc:'مشاركة بيانات الحساب مع أي شخص آخر ممنوعة وتؤدي إلى إغلاق الحساب فوراً.',
  rule9_title:'حظر التحوط (Hedging)', rule9_desc:'فتح صفقات متعاكسة على نفس الرمز أو رموز مترابطة بين عدة حسابات لنفس المتداول ممنوع. (التحوط الجماعي محظور، وفي حال اكتشافه يؤدي إلى إغلاق جميع الحسابات ذات الصلة.)',
  rule10_title:'حظر نسخ الصفقات بين الحسابات', rule10_desc:'نسخ الصفقات بين عدة حسابات ممنوع، وعند اكتشافه تتم مراجعة الحسابات وقد تُغلق.',
  rule11_title:'حظر استغلال فروق التأخير السعري', rule11_desc:'استغلال التأخير بين مصادر التسعير لتحقيق ربح دون مخاطرة سوقية حقيقية ممنوع.',
  rule12_title:'الروبوتات والمستشارون الخبراء', rule12_desc:'الروبوتات التي تستغل أخطاء الخادم ممنوعة؛ الاستخدام العادي لـ EA مسموح.',
  rule13_title:'حصة الربح من الحساب الممول', rule13_desc:'في الحساب الممول، الحصة الأساسية للمتداول من الربح 75% (خطة خطوة واحدة) أو 80% (خطة خطوتين/ثلاث خطوات) أو 50% (خطة التمويل الفوري). مع كل توسع للحساب (كل 10% من الربح المحقق)، تزداد هذه الحصة 5 نقاط مئوية، حتى سقف 100%.',
  rule14_title:'جدول السحب', rule14_desc:'بالنسبة لأول عملية سحب، يجب أن تمر 14 يوماً على الأقل منذ أول صفقة لك في الحساب الممول. بعد ذلك، يجب أن يكون كل سحب لاحق بعد 7 أيام على الأقل من السحب السابق. يتم الدفع خلال 48 ساعة من الموافقة.',
  rule15_title:'التنفيذ العادل والموحد', rule15_desc:'يتم تطبيق السبريد والعمولة والانزلاق السعري بشكل متطابق على كل متداول وفق هذه القواعد الثابتة والمعلنة. لا يتم تعديلها يدويًا أو استهداف متداول معين لإسقاطه أبدًا.',
  rules_footer_note:'يؤدي انتهاك أي من هذه القوانين إلى إغلاق تلقائي للحساب و/أو مراجعة يدوية من فريقنا.',

