  rules_eyebrow:'Правила', rules_h1:'Правила испытания и профинансированного счёта',
  rules_p:'Прочитайте перед покупкой. Оплата означает согласие с правилами.',
  rules_lang_note:'Эта страница переведена на все 7 языков сайта.',
  rules_section_caps:'Лимиты счёта', rules_section_risk:'Правила риска', rules_section_general:'Общие правила',
  rule1_title:'Максимальный размер счёта', rule1_desc:'Не более $500,000 на один счёт.',
  rule2_title:'Максимальный капитал на трейдера', rule2_desc:'Суммарно не более $750,000 на активных/профинансированных счетах.',
  rule3_title:'Максимум активных счетов', rule3_desc:'Не более 3 активных счетов одновременно.',
  rule4_title:'Правило плавающего риска', rule4_desc:'Риск одной сделки или суммарный риск одновременно открытых сделок не должен превышать 3% счёта (для размеров $1,000–$50,000) или 2% (для размеров от $100,000). Превышение этого лимита из-за проскальзывания не считается нарушением; нарушением считается только преднамеренное превышение (без установленного стоп-лосса, при реальном падении капитала счёта ниже лимита).',
  rule5_title:'Минимум торговых дней', rule5_desc:'Минимум 3 торговых дня с прибылью не менее 0.5% каждый — для прохождения любого этапа оценки, а также (на самом профинансированном счёте) как условие первой выплаты, во всех планах, включая мгновенное финансирование.',
  rule6_title:'Правило 80% на сделку', rule6_desc:'Прибыль ни одной сделки не может составлять более 80% прибыли этапа (или, в плане мгновенного финансирования, общей прибыли с момента открытия счёта).',
  rule7_title:'Правило консистентности 40%', rule7_desc:'На профинансированном счёте день не может давать более 40% общей прибыли.', rule16_title:'Определение «торгового дня»', rule16_desc:'Торговый день определяется по полуночи UTC — не по вашему местному времени.', rule17_title:'Маржин-колл', rule17_desc:'Если плавающий убыток превышает свободную маржу, все позиции закрываются немедленно.', rule18_title:'Возврат платы за челлендж', rule18_desc:'Плата за челлендж полностью возвращается, в дополнение к вашей доле прибыли, при первом успешном запросе выплаты с профинансированного счёта.',
  rule8_title:'Запрет передачи CID', rule8_desc:'Передача данных счёта запрещена, ведёт к закрытию счёта.',
  rule9_title:'Запрет хеджирования', rule9_desc:'Открытие противоположных позиций по одному символу или коррелирующим символам между собственными счетами трейдера запрещено. (Групповое хеджирование запрещено и, в случае обнаружения, приводит к закрытию ВСЕХ связанных счетов.)',
  rule10_title:'Запрет копи-трейдинга', rule10_desc:'Копирование сделок между счетами запрещено.',
  rule11_title:'Запрет латентного арбитража', rule11_desc:'Использование задержек котировок запрещено.',
  rule12_title:'Боты и советники', rule12_desc:'Боты, использующие баги сервера, запрещены; обычные EA разрешены.',
  rule13_title:'Доля прибыли на профинансированном счёте', rule13_desc:'Базовая доля трейдера в прибыли — 75% (один этап), 80% (два/три этапа) или 50% (план мгновенного финансирования). При каждом масштабировании счёта (за каждые 10% реализованной прибыли) эта доля увеличивается на 5 процентных пунктов, до потолка в 100%.',
  rule14_title:'График выплат', rule14_desc:'Для первой выплаты должно пройти не менее 14 дней с вашей первой сделки на профинансированном счёте. После этого каждая следующая выплата должна быть не ранее чем через 7 дней после предыдущей. Выплата производится в течение 48 часов после одобрения.',
  rule15_title:'Честное и единое исполнение', rule15_desc:'Спред, комиссия и проскальзывание применяются одинаково ко всем трейдерам согласно этим фиксированным, опубликованным правилам. Они никогда не настраиваются вручную и не нацелены на то, чтобы обвалить конкретного трейдера.',
