  disclaimer_text:'FundedBeyondBorders es una plataforma educativa de evaluación de trading. Todas las cuentas son simuladas. No somos un bróker ni asesor financiero, y no garantizamos ganancias.',
  chat_title:'Soporte en Vivo', chat_body:'¿Tienes una pregunta? Escríbenos.', chat_placeholder:'Escribe tu mensaje...', chat_send:'Enviar',
