function currentLang() { return localStorage.getItem('fbb_lang') || 'en'; }

function applyI18n(lang) {
  document.documentElement.lang = lang;
  document.documentElement.dir = RTL_LANGS.includes(lang) ? 'rtl' : 'ltr';
  localStorage.setItem('fbb_lang', lang);

  document.querySelectorAll('[data-i18n]').forEach(el => {
    const key = el.getAttribute('data-i18n');
    const text = I18N[lang]?.[key] ?? I18N.en[key];
    if (text != null) el.textContent = text;
  });
  document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
    const key = el.getAttribute('data-i18n-placeholder');
    const text = I18N[lang]?.[key] ?? I18N.en[key];
    if (text != null) el.placeholder = text;
  });
  document.querySelectorAll('.lang-current-label').forEach(el => { el.textContent = LANG_NAMES[lang]; });
  document.querySelectorAll('.lang-menu button').forEach(b => b.classList.toggle('active', b.dataset.lang === lang));

  document.dispatchEvent(new CustomEvent('fbb:langchange', { detail: { lang } }));
}

function initLangMenu() {
  const btn = document.querySelector('.lang-btn');
  const menu = document.querySelector('.lang-menu');
  if (!btn || !menu) return;
  btn.addEventListener('click', () => menu.classList.toggle('open'));
  document.addEventListener('click', (e) => { if (!btn.contains(e.target) && !menu.contains(e.target)) menu.classList.remove('open'); });
  menu.querySelectorAll('button').forEach(b => {
    b.addEventListener('click', () => { applyI18n(b.dataset.lang); menu.classList.remove('open'); });
  });
}

document.addEventListener('DOMContentLoaded', () => { initLangMenu(); applyI18n(currentLang()); });
